(function($){"use strict";if(typeof __sq_subscriptionexpired_text==="undefined")var __sq_subscriptionexpired_text="";if(typeof __sq_couldnotprocess_text==="undefined")var __sq_couldnotprocess_text="";$.fn.sq_postslist=function(posts){var $this=this;$this.inArray=function(id,array){if(array.length===0)return false;for(var i=0;i<array.length;i++){if(array[i]===id){return true}}return false};$this.getRanks=function(){var $current_rows=$this.find(".sq_slacolumn_row");var $current_row;$.post(ajaxurl,{action:"sq_ajax_postslist",posts:posts,post_type:$this.find("input[name=post_type]").val(),sq_nonce:sqAdmin.nonce}).done(function(response){if(typeof response.error!=="undefined"&&response.error==="subscription_expired"){$current_rows.each(function(){$(this).removeClass("sq_minloading").html('<span class="sq_no_rank">'+__sq_subscriptionexpired_text+"</span>")})}else{$current_rows.each(function(){if(!$this.inArray(jQuery(this).attr("ref"),posts)){$(this).removeClass("sq_minloading").html('<span class="sq_no_rank" ref="'+$(this).attr("ref")+'">'+__sq_ranknotpublic_text+"</span>")}});if(typeof response.posts!=="undefined"){var current;for(current in response.posts){$current_row=$this.find(".sq_slacolumn_row[ref='"+current+"']");if(typeof response.posts[current]!=="undefined"){$current_row.removeClass("sq_minloading").html(response.posts[current]);if($current_row.find(".sq_optimize").length>0){$current_row.find(".sq_optimize").on("click",function(){location.href=sqAdmin.adminposturl+"?post="+current+"&action=edit"})}}}}else{$current_rows.each(function(){$(this).removeClass("sq_minloading").html('<span class="sq_no_rank" ref="'+current+'">'+__sq_couldnotprocess_text+"</span>")})}}})};return $this};function sqLoadInspect(postId,url){var $body=$("#sq_inspect_body");$("#sq_inspect_overlay").attr("data-post_id",postId).attr("data-url",url||"").show();$body.html('<div style="padding:30px;text-align:center;color:#888;">Loading…</div>');$.post(ajaxurl,{action:"sq_focuspages_inspecturl",post_id:postId,url:url||"",sq_nonce:sqAdmin.nonce}).done(function(response){if(response&&typeof response.html!=="undefined"&&response.html){$body.html(response.html)}else{$body.html('<div style="padding:30px;text-align:center;color:#888;">Page could not load</div>')}}).fail(function(){$body.html('<div style="padding:30px;text-align:center;color:#888;">Page could not load</div>')},"json")}$(document).ready(function(){if(typeof sq_posts!=="undefined"){$(".wrap").sq_postslist(sq_posts).getRanks()}$(document).on("click",".sq_inspecturl_link",function(e){e.preventDefault();sqLoadInspect($(this).attr("data-post_id"),$(this).attr("data-url"))});$(document).on("click","#sq_inspect_refresh",function(){var postId=$("#sq_inspect_overlay").attr("data-post_id");if(postId){sqLoadInspect(postId,$("#sq_inspect_overlay").attr("data-url"))}});$(document).on("click","#sq_inspect_close",function(){$("#sq_inspect_overlay").hide()});$(document).on("click","#sq_inspect_overlay",function(e){if(e.target===this){$(this).hide()}})})})(jQuery);